import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

function AdminUserManagementPage() {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  const token = localStorage.getItem("token");
  const isAdmin = localStorage.getItem("is_staff") === "true";

  useEffect(() => {
    if (!token || !isAdmin) {
      navigate("/login");
      return;
    }
    fetchUsers();
    fetchStats();
  }, [token, isAdmin, navigate]);

  const fetchUsers = async () => {
    try {
      const url = searchTerm
        ? `http://127.0.0.1:8000/api/admin/users/?search=${encodeURIComponent(searchTerm)}`
        : "http://127.0.0.1:8000/api/admin/users/";
      
      const res = await fetch(url, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) {
        throw new Error("Не вдалося завантажити користувачів");
      }

      const data = await res.json();
      setUsers(data);
      setLoading(false);
    } catch (err) {
      console.error("Помилка завантаження користувачів:", err);
      setError("Помилка завантаження користувачів");
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/api/admin/users/stats/", {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        setStats(data);
      }
    } catch (err) {
      console.error("Помилка завантаження статистики:", err);
    }
  };

  const handleTogglePremium = async (userId) => {
    try {
      const res = await fetch(
        `http://127.0.0.1:8000/api/admin/users/${userId}/toggle_premium/`,
        {
          method: "POST",
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      if (!res.ok) {
        throw new Error("Не вдалося змінити статус преміум");
      }

      // Refresh users list
      fetchUsers();
      fetchStats();
    } catch (err) {
      console.error("Помилка зміни статусу:", err);
      alert("Помилка зміни статусу преміум");
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    fetchUsers();
  };

  if (loading) {
    return <div style={{ padding: "2rem" }}>Завантаження...</div>;
  }

  return (
    <div style={{ padding: "2rem", maxWidth: "1200px", margin: "0 auto" }}>
      <h1>Управління користувачами</h1>

      {stats && (
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
            gap: "1rem",
            marginBottom: "2rem",
          }}
        >
          <div style={{ padding: "1rem", background: "#f5f5f5", borderRadius: "8px" }}>
            <h3>Всього користувачів</h3>
            <p style={{ fontSize: "2rem", margin: 0 }}>{stats.total_users}</p>
          </div>
          <div style={{ padding: "1rem", background: "#e3f2fd", borderRadius: "8px" }}>
            <h3>Преміум користувачі</h3>
            <p style={{ fontSize: "2rem", margin: 0 }}>{stats.premium_users}</p>
          </div>
          <div style={{ padding: "1rem", background: "#fff3e0", borderRadius: "8px" }}>
            <h3>Адміністратори</h3>
            <p style={{ fontSize: "2rem", margin: 0 }}>{stats.admin_users}</p>
          </div>
          <div style={{ padding: "1rem", background: "#f1f8e9", borderRadius: "8px" }}>
            <h3>Звичайні користувачі</h3>
            <p style={{ fontSize: "2rem", margin: 0 }}>{stats.regular_users}</p>
          </div>
        </div>
      )}

      {error && <div style={{ color: "red", marginBottom: "1rem" }}>{error}</div>}

      <form onSubmit={handleSearch} style={{ marginBottom: "1rem" }}>
        <input
          type="text"
          placeholder="Пошук за ім'ям або email..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ padding: "0.5rem", width: "300px", marginRight: "0.5rem" }}
        />
        <button type="submit">Пошук</button>
        {searchTerm && (
          <button
            type="button"
            onClick={() => {
              setSearchTerm("");
              fetchUsers();
            }}
            style={{ marginLeft: "0.5rem" }}
          >
            Очистити
          </button>
        )}
      </form>

      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr style={{ background: "#f5f5f5" }}>
            <th style={{ padding: "0.75rem", textAlign: "left", border: "1px solid #ddd" }}>
              ID
            </th>
            <th style={{ padding: "0.75rem", textAlign: "left", border: "1px solid #ddd" }}>
              Ім'я користувача
            </th>
            <th style={{ padding: "0.75rem", textAlign: "left", border: "1px solid #ddd" }}>
              Email
            </th>
            <th style={{ padding: "0.75rem", textAlign: "left", border: "1px solid #ddd" }}>
              Адмін
            </th>
            <th style={{ padding: "0.75rem", textAlign: "left", border: "1px solid #ddd" }}>
              Преміум
            </th>
            <th style={{ padding: "0.75rem", textAlign: "left", border: "1px solid #ddd" }}>
              Дата реєстрації
            </th>
            <th style={{ padding: "0.75rem", textAlign: "left", border: "1px solid #ddd" }}>
              Дії
            </th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => (
            <tr key={user.id}>
              <td style={{ padding: "0.75rem", border: "1px solid #ddd" }}>{user.id}</td>
              <td style={{ padding: "0.75rem", border: "1px solid #ddd" }}>{user.username}</td>
              <td style={{ padding: "0.75rem", border: "1px solid #ddd" }}>{user.email}</td>
              <td style={{ padding: "0.75rem", border: "1px solid #ddd" }}>
                {user.is_staff ? "✓" : ""}
              </td>
              <td style={{ padding: "0.75rem", border: "1px solid #ddd" }}>
                {user.is_premium ? "✓" : ""}
              </td>
              <td style={{ padding: "0.75rem", border: "1px solid #ddd" }}>
                {new Date(user.date_joined).toLocaleDateString()}
              </td>
              <td style={{ padding: "0.75rem", border: "1px solid #ddd" }}>
                <button
                  onClick={() => handleTogglePremium(user.id)}
                  style={{
                    padding: "0.5rem 1rem",
                    background: user.is_premium ? "#f44336" : "#4caf50",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    cursor: "pointer",
                  }}
                >
                  {user.is_premium ? "Прибрати преміум" : "Додати преміум"}
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {users.length === 0 && (
        <p style={{ textAlign: "center", marginTop: "2rem" }}>Користувачів не знайдено</p>
      )}
    </div>
  );
}

export default AdminUserManagementPage;
